    'admin_fair-defaults.ai_disabled_help' => 'Los cálculos FAIR asistidos por IA requieren que haya una plataforma de IA (OpenWebUI o LibreChat) habilitada. <a href="admin.php?section=ai-integration">Configure primero los ajustes de integración de IA</a>.',
