    'admin_shadow-saas-grip.abort_failed_prefix' => 'No se pudo cancelar la sincronización: ',
    'admin_shadow-saas-grip.abort_grip_confirm' => '¿Cancelar la sincronización de Grip en ejecución?',
    'admin_shadow-saas-grip.abort_hero_confirm' => '¿Cancelar la sincronización de HERO en ejecución?',
    'admin_shadow-saas-grip.about_grip_body' => 'Grip Security descubre y supervisa de forma continua las aplicaciones SaaS de registro en todo su entorno.
Esta integración:<br><br>
<strong>&bull; Refleja los datos de Grip:</strong> Extrae el inventario completo de SaaS / usuarios / alertas hacia las tablas <code>shadow_saas_grip_*</code>.<br>
<strong>&bull; Hidrata Shadow SaaS:</strong> Proyecta cada aplicación SaaS en la lista existente de Shadow SaaS, normalizando la URL a su dominio registrable para que la coincidencia de proveedores funcione igual que una importación CSV.<br>
<strong>&bull; Realiza seguimiento del riesgo:</strong> Conserva la puntuación de riesgo de Grip, la etiqueta de sanción, los recuentos de ámbitos OAuth, la clasificación de profundidad de IA, la compatibilidad con MFA / SAML y los metadatos del contacto principal.<br>
<strong>&bull; Se mantiene actualizada:</strong> Se vuelve a ejecutar según la programación cron configurada; los administradores también pueden desencadenar una ejecución inmediata en segundo plano con el botón "Ejecutar ahora" de arriba.',
    'admin_shadow-saas-grip.about_grip_heading' => 'Acerca de la integración con Grip',
    'admin_shadow-saas-grip.about_hero_body' => 'HERO Security descubre los proveedores SaaS de terceros y las incidencias que los afectan en todo su entorno.
Esta integración:<br><br>
<strong>&bull; Refleja los datos de HERO:</strong> Extrae proveedores / incidencias / usuarios por proveedor hacia las tablas <code>shadow_saas_hero_*</code>.<br>
<strong>&bull; Hidrata Shadow SaaS:</strong> Proyecta cada proveedor en la lista existente de Shadow SaaS por dominio registrable, de modo que la coincidencia funcione igual que una importación CSV.<br>
<strong>&bull; Realiza seguimiento del riesgo:</strong> Deriva una puntuación de riesgo de 1 a 5 a partir de la peor incidencia abierta por proveedor (la misma escala de 1 a 5 que usa Grip) y registra el estado del proveedor y los aspectos de la relación.<br>
<strong>&bull; Se mantiene actualizada:</strong> Se vuelve a ejecutar en el trabajo compartido de Rehidratación programada; los administradores también pueden desencadenar una ejecución inmediata con el botón "Ejecutar ahora" de abajo.',
    'admin_shadow-saas-grip.about_hero_heading' => 'Acerca de la integración con HERO',
    'admin_shadow-saas-grip.api_key_label' => 'Clave de API',
    'admin_shadow-saas-grip.api_reference_heading' => 'Referencia de la API',
    'admin_shadow-saas-grip.api_token_help' => 'Se envía como el encabezado HTTP <code>access-token</code> en cada solicitud. Déjelo en blanco para conservar el token existente.',
    'admin_shadow-saas-grip.api_token_label' => 'Token de API',
    'admin_shadow-saas-grip.api_url_host_not_allowed' => 'El host de la URL de la API no está permitido.',
    'admin_shadow-saas-grip.api_url_invalid' => 'La URL de la API debe ser una URL http(s) válida.',
    'admin_shadow-saas-grip.api_url_label' => 'URL de la API',
    'admin_shadow-saas-grip.apps_with_users_suffix' => ' aplicaciones con usuarios',
    'admin_shadow-saas-grip.client_id_label' => 'Client ID',
    'admin_shadow-saas-grip.client_secret_label' => 'Client Secret',
    'admin_shadow-saas-grip.currently_holding_prefix' => 'Actualmente contiene ',
    'admin_shadow-saas-grip.data_source_help' => '<strong>En vivo</strong> llama a la API de Grip en cada página (siempre actual, más carga sobre la API). <strong>Local (hidratado/en caché)</strong> sirve las tablas <code>shadow_saas_grip_*</code> hidratadas en la base de datos (menos carga sobre la API), y una instantánea por aplicación que falte se obtiene de la API una vez y luego se almacena en caché. En modo Local, cada sincronización <strong>actualiza por completo</strong> los datos: las tablas espejo de Grip se truncan y se vuelven a hidratar desde la API.',
    'admin_shadow-saas-grip.data_source_label' => 'Origen de datos',
    'admin_shadow-saas-grip.data_source_live' => 'En vivo: consultar la API de Grip en cada visualización',
    'admin_shadow-saas-grip.data_source_local' => 'Local (hidratado/en caché): servir desde la base de datos',
    'admin_shadow-saas-grip.download_postman_json' => 'Descargar Postman (JSON)',
    'admin_shadow-saas-grip.download_swagger_yaml' => 'Descargar Swagger (YAML)',
    'admin_shadow-saas-grip.enable_grip' => 'Habilitar la integración con Grip Security',
    'admin_shadow-saas-grip.enable_hero' => 'Habilitar la integración con HERO Security',
    'admin_shadow-saas-grip.enable_scheduled_rehydration' => 'Habilitar la rehidratación programada',
    'admin_shadow-saas-grip.enable_zscaler' => 'Habilitar el bloqueo por Categoría de URL de Zscaler al Denegar',
    'admin_shadow-saas-grip.enter_admin_api_key' => 'Introduzca la clave de API del administrador',
    'admin_shadow-saas-grip.failed_truncate_prefix' => 'No se pudo truncar ',
    'admin_shadow-saas-grip.flow_grip_breach_label' => 'Canalizar la información de brechas de Grip hacia Alertas de Brecha&nbsp;/&nbsp;Ciberseguridad',
    'admin_shadow-saas-grip.grip_all_cleared_p1' => 'Se borraron todos los datos de Grip: ',
    'admin_shadow-saas-grip.grip_all_cleared_p2' => ' tabla(s) espejo truncada(s), ',
    'admin_shadow-saas-grip.grip_all_cleared_p3' => ' fila(s) de Shadow SaaS eliminada(s) y ',
    'admin_shadow-saas-grip.grip_all_cleared_p4' => ' registro(s) de proveedor con la telemetría de Grip estampada borrada.',
    'admin_shadow-saas-grip.grip_api_reference_intro' => 'Inventario de endpoints de la API pública de Grip Security (base del servidor <code>https://&lt;tenant&gt;.dep.grip.security/public</code>, OpenAPI 3.1 autogenerado). La sincronización de FairTPRM consume los endpoints de lectura (GET) marcados como <em>usados por la sincronización</em>; el inventario completo &mdash; incluidos los grupos Users, Workflows, Posture&nbsp;Management, AuditLogs, Alerts / Alerts&nbsp;V2, Actions y AI&nbsp;Agents &mdash; está en las descargas de OpenAPI y Postman de abajo. La extracción de dominios normaliza las URL a su dominio registrable (p. ej. <code>https://www.united.com</code> → <code>united.com</code>, <code>http://color.redhat.com</code> → <code>redhat.com</code>).',
    'admin_shadow-saas-grip.grip_auth_help' => 'Encabezado de autenticación: <code>access-token: &lt;your-token&gt;</code>. La variable <code>accessToken</code> de la colección de Postman está establecida en <code>REPLACE_ME</code>; sustitúyala por el token de su tenant antes de enviar solicitudes.',
    'admin_shadow-saas-grip.grip_base_url_help' => 'URL de Grip con prefijo de tenant y raíz en <code>/public/saas</code> (p. ej. <code>https://tenant.dep.grip.security/public/saas</code>). Los endpoints hermanos (<code>/public/users</code>, <code>/public/alerts</code>) se derivan de este host.',
    'admin_shadow-saas-grip.grip_base_url_label' => 'Servidor (URL base del tenant)',
    'admin_shadow-saas-grip.grip_breach_help' => 'En cada rehidratación programada (y con la opción manual <strong>Ejecutar&nbsp;ahora</strong> de abajo), las alertas "Security Incident Detected" de Grip se registran en el sistema de <a href="breach-alerts.php">Alertas de Brecha&nbsp;/&nbsp;Ciberseguridad</a> (sin duplicados). Las brechas de un proveedor incorporado se vinculan a ese proveedor; las brechas de una aplicación sin proveedor incorporado se registran igualmente y se etiquetan como <strong>Shadow&nbsp;SaaS</strong> con el número de usuarios potencialmente afectados. Requiere que Grip esté habilitado (arriba) <em>y</em> la opción de Alerta de Brecha&nbsp;/&nbsp;Ciberseguridad en <a href="admin.php?section=email">Correo electrónico &amp; Alertas</a>.',
    'admin_shadow-saas-grip.grip_config_update_failed_prefix' => 'No se pudo actualizar la configuración de Grip: ',
