    'admin_shadow-saas-grip.grip_connection_heading' => 'Conexión con Grip Security',
    'admin_shadow-saas-grip.grip_enable_help' => 'Cuando está habilitada, las sincronizaciones programadas y bajo demanda extraerán las aplicaciones SaaS, los usuarios y las alertas de su tenant de Grip hacia la lista de Shadow SaaS.',
