    'admin_shadow-saas-grip.hero_api_reference_intro' => 'Inventario de endpoints de la API pública de HERO usada por esta integración. La autenticación es OAuth 2.0 con credenciales de cliente &rarr; token Bearer; los endpoints de listado usan paginación por cursor (<code>next_cursor</code> &rarr; <code>cursor</code>).',
    'admin_shadow-saas-grip.hero_auth_help' => 'Autenticación: <code>Authorization: Bearer &lt;token&gt;</code> en todos los endpoints de datos. Los tokens caducan al cabo de ~1 hora.',
    'admin_shadow-saas-grip.hero_base_url_help' => 'Base de la API pública de HERO, p. ej. <code>https://api.herosecurity.ai/stable</code>. Los endpoints (<code>/v1/vendors</code>, <code>/v1/issues</code>) se derivan de este host.',
