    'admin_shadow-saas-grip.hero_mirror_vendors_desc' => 'Una fila por cada proveedor de HERO (estado, aspectos, puntuación de riesgo derivada de 1 a 5, payload completo).',
    'admin_shadow-saas-grip.hero_pacing_help' => 'HERO limita la frecuencia de las llamadas a la API (~60 solicitudes por minuto, para toda la cuenta). Estos ajustes controlan el ritmo de la sincronización de usuarios por proveedor.',
    'admin_shadow-saas-grip.hero_security_link' => 'HERO Security &rarr;',
