    'admin_shadow-saas-grip.hero_throttle_help' => 'Pausa entre la solicitud de usuarios de cada proveedor. ~1100&nbsp;ms mantiene una sincronización completa justo por debajo del límite de ~60/min de HERO. Un valor menor es más rápido pero desencadena esperas por límite de frecuencia (429).',
    'admin_shadow-saas-grip.hero_throttle_label' => 'Pausa entre llamadas de proveedor (ms)',
