    'admin_shadow-saas-grip.zscaler_enable_help' => 'Cuando está habilitado, el botón Denegar de Shadow SaaS insertará el dominio del proveedor en la Categoría de URL configurada. Cuando está deshabilitado, Denegar solo actualiza el estado local.',
    'admin_shadow-saas-grip.zscaler_intro' => 'Cuando se deniega un proveedor de la lista de Shadow SaaS, el dominio del proveedor se añade a la Categoría de URL de abajo en Zscaler ZIA (usando <code>action=ADD_TO_LIST</code>) y luego se activa. Compartido por ambos proveedores.',
    'admin_shadow-saas-grip.zscaler_password_help' => 'El <code>client_secret</code> que se muestra <strong>una sola vez</strong> cuando se creó el API Client. Se almacena cifrado. Déjelo en blanco para conservar el valor existente.',
