    'admin_shadow-saas-grip.zscaler_username_placeholder' => 'UUID de ZIdentity → Integration → API Clients',
    'admin_shadow-saas-grip.zscaler_vanity_help' => 'Host del endpoint de token OAuth del tenant de ZIdentity: la URL del token es <code>https://&lt;vanity&gt;/oauth2/v1/token</code>. Encuéntrelo en la URL de administración de ZIdentity (la parte anterior a <code>.zslogin.net</code>).',
    'admin_shadow-saas-grip.zscaler_vanity_label' => 'Dominio personalizado de ZIdentity',
    'admin_shodan-srs.about_body' => 'Shodan es una plataforma de inteligencia de internet que escanea e indexa todos los dispositivos conectados a internet que puede encontrar. La integración permite:<br><br><strong>• Escaneo de puertos:</strong> Identificar puertos abiertos en la infraestructura del proveedor, incluidos servicios de alto riesgo (FTP, Telnet, RDP, SMB)<br><strong>• Detección de vulnerabilidades:</strong> Descubrir CVE conocidos asociados a las direcciones IP y los servicios del proveedor<br><strong>• Identificación de servicios:</strong> Catalogar los servicios en ejecución, las versiones de software y las configuraciones del servidor<br><strong>• Puntuación de seguridad:</strong> Generar una puntuación de seguridad de 0 a 100 basada en la superficie de ataque expuesta',
    'admin_shodan-srs.about_heading' => 'Acerca de Shodan',
    'admin_shodan-srs.about_learn_more' => 'Más información sobre Shodan →',
    'admin_shodan-srs.about_note_body' => 'Las puntuaciones de Shodan son complementarias a las de UpGuard. UpGuard se centra en la postura de seguridad general (escala de 0 a 950), mientras que Shodan se centra en la infraestructura expuesta (escala de 0 a 100). Ambas se pueden habilitar simultáneamente para realizar evaluaciones integrales de proveedores.',
    'admin_shodan-srs.about_note_label' => 'Nota:',
    'admin_shodan-srs.across' => 'en',
    'admin_shodan-srs.active_waiver_singular' => 'exención activa',
    'admin_shodan-srs.active_waivers_plural' => 'exenciones activas',
    'admin_shodan-srs.api_key_help' => 'Clave de API de su <a href="https://account.shodan.io" target="_blank">cuenta de Shodan</a>. Déjela en blanco para conservar la clave existente.',
    'admin_shodan-srs.api_key_label' => 'Clave de API de Shodan',
    'admin_shodan-srs.api_key_placeholder' => 'Introduzca la clave de API',
    'admin_shodan-srs.banner_max_age_help' => 'Ignora los datos de banner de Shodan con una antigüedad superior a este número de días. Shodan conserva datos históricos de puertos que ahora podrían estar filtrados o cerrados. Establézcalo en 0 para deshabilitar el filtrado por actualidad. Predeterminado: 7 días.',
    'admin_shodan-srs.banner_max_age_label' => 'Antigüedad máxima del banner (días)',
