    'admin_shodan-srs.min_cve_year_help_prefix' => 'Excluye de los resultados del escaneo los CVE publicados antes de este año. Predeterminado: 0 = automático (año actual menos 5, actualmente ',
    'admin_shodan-srs.min_cve_year_help_suffix' => '). La detección basada en banners de Shodan a menudo asocia CVE muy antiguos con cadenas de versión de software, lo que produce falsos positivos. Establezca un año específico para anularlo, o déjelo en 0 para usar la ventana móvil de 5 años.',
