    'admin_shodan-srs.on_demand_help' => 'Cuando está habilitado, Shodan solicitará un escaneo bajo demanda para cualquier IP de la que no tenga datos existentes durante la puntuación. Esto garantiza la cobertura de dominios que Shodan no ha escaneado previamente, pero consume créditos de escaneo (1 crédito por IP) y añade hasta 3 minutos de tiempo de espera por cada solicitud de puntuación mientras Shodan procesa el escaneo. Recomendado para proveedores en los que Shodan no devuelve señales de seguridad.',
    'admin_shodan-srs.on_demand_label' => 'Habilitar el escaneo bajo demanda',
    'admin_shodan-srs.randomize_subdomains_help' => 'Cuando está habilitado, los subdominios se eligen de forma aleatoria en lugar de alfabéticamente. Ofrece una cobertura más amplia en escaneos repetidos.',
