    'admin_shodan-srs.rescan_cooldown_help' => 'Suprime las solicitudes de reescaneo duplicadas para las IP ya reescaneadas dentro de esta ventana. Cada reescaneo consume créditos de escaneo de Shodan, por lo que esto evita cargos repetidos accidentales por dobles clics o reescaneos manuales consecutivos. Establézcalo en 0 para deshabilitar el tiempo de espera (cada clic reescanea todas las IP). Predeterminado: 24 horas.',
