    'admin_shodan-srs.weights_intro' => 'Ajuste cuánto contribuye cada categoría de seguridad a la puntuación final. Los pesos son relativos: no necesitan sumar exactamente 100, pero se normalizarán proporcionalmente.',
    'admin_shodan-srs.weights_warning' => 'Los pesos no suman el 100 %; se normalizarán proporcionalmente al calcular la puntuación final.',
    'admin_shodan-srs.word_vendor' => 'proveedor',
    'admin_shodan-srs.word_vendors' => 'proveedores',
    'admin_shodan-srs.word_waiver' => 'exención',
    'admin_shodan-srs.word_waivers' => 'exenciones',
    'admin_srs.about_custom_body' => 'La puntuación personalizada le permite introducir manualmente puntuaciones de seguridad para proveedores mediante herramientas de evaluación externas o servicios de calificación.<br><br><strong>Rango de puntuación:</strong> 1-100 (escala porcentual)<br><strong>Calificación:</strong> A &ge; 90, B &ge; 75, C &ge; 60, D &ge; 40, F &lt; 40<br><br>Cuando existen varias fuentes de puntuación (UpGuard, Shodan, Personalizada), se calcula y muestra una puntuación promedio combinada en toda la aplicación. Esto proporciona una vista unificada de la postura de seguridad de cada proveedor a partir de todas las fuentes disponibles.',
    'admin_srs.about_custom_heading' => 'Acerca de la puntuación personalizada',
    'admin_srs.about_upguard_body' => 'UpGuard CyberRisk proporciona calificaciones de seguridad automatizadas y supervisión continua de proveedores externos. La integración permite:<br><br><strong>• Puntuación de seguridad automatizada:</strong> obtenga calificaciones de seguridad instantáneas (0-950) para los proveedores según su postura de seguridad externa<br><strong>• Identificación de riesgos:</strong> identifique automáticamente riesgos de seguridad de gravedad alta, media y baja<br><strong>• Análisis de tendencias:</strong> haga un seguimiento de las puntuaciones de seguridad de los proveedores a lo largo del tiempo para detectar mejoras o deterioros<br><strong>• Supervisión basada en niveles:</strong> configure la frecuencia de recalificación según la criticidad del proveedor',
    'admin_srs.about_upguard_heading' => 'Acerca de UpGuard CyberRisk',
    'admin_srs.about_upguard_learn_more' => 'Más información sobre UpGuard CyberRisk &rarr;',
    'admin_srs.api_key_help' => 'Clave de API de la consola de UpGuard CyberRisk. Déjela en blanco para conservar la clave existente.',
