    'admin_srs.cron_job_required' => 'Se requiere un trabajo cron',
    'admin_srs.cron_lock_files_note' => 'Usa archivos de bloqueo para evitar ejecuciones superpuestas. Consulte la <span data-action="openCronInfoModal" style="color: var(--theme-header-color, #2563eb); cursor: pointer; text-decoration: underline;">Guía de configuración de Cron</span> para obtener más detalles.',
    'admin_srs.cron_modal_heading' => 'Configuración del trabajo cron para la recalificación de SRS',
    'admin_srs.cron_note_body' => 'El historial de ejecución se registra en la base de datos. Consulte Admin &gt; SRS para ver ejecuciones anteriores y cualquier error.',
    'admin_srs.cron_ondemand_desc' => 'Procesa las solicitudes de recalificación manual puestas en cola desde la página de detalles del proveedor. <strong>Necesario</strong> cuando "Usar Cron para la recalificación" está habilitado en cualquiera de las integraciones:',
    'admin_srs.cron_ondemand_heading' => '2. Cola de recalificación bajo demanda <span style="background: #dbeafe; color: #1e40af; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 600; vertical-align: middle;">Necesario para "Usar Cron"</span>',
    'admin_srs.cron_ondemand_note' => 'Se ejecuta cada minuto. Usa archivos de bloqueo para evitar ejecuciones superpuestas. Solo procesa un proveedor a la vez para evitar los límites de tasa de la API. Si no existen recalificaciones pendientes, el trabajo finaliza de inmediato.',
    'admin_srs.cron_prereq_enabled' => 'Asegúrese de que al menos una integración de SRS esté habilitada con una clave de API válida',
    'admin_srs.cron_prereq_log_dir' => 'Cree el directorio de registros si es necesario: <code style="background: #f8f9fa; padding: 2px 6px; border-radius: 3px;">sudo mkdir -p /var/log</code>',
    'admin_srs.cron_prereq_php_cli' => 'Verifique que PHP CLI esté instalado: <code style="background: #f8f9fa; padding: 2px 6px; border-radius: 3px;">php -v</code>',
